using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatClientBuilder =>
    chatClientBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18",
        new OpenAIClient(
            builder.Configuration["AI:ApiKey"]
                ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
                ?? throw new InvalidOperationException(
                    "Set AI:ApiKey in config or OPENAI_API_KEY environment variable."))));

builder.Services.AddSingleton<Notepad>();
builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddHostedService<ResearchAgentService>();

using var host = builder.Build();
await host.RunAsync();

// ── Notepad: in-memory store for research notes ──

public sealed class Notepad
{
    private readonly List<NoteEntry> _notes = [];
    private int _nextId = 1;

    public int Add(string title, string content)
    {
        var id = _nextId++;
        _notes.Add(new NoteEntry(id, title, content, DateTime.UtcNow));
        return id;
    }

    public IReadOnlyList<NoteEntry> GetAll() => _notes.AsReadOnly();

    public string FormatAll()
    {
        if (_notes.Count == 0)
            return "(no notes yet)";

        return string.Join("\n\n", _notes.Select(n =>
            $"[Note #{n.Id}] {n.Title} ({n.Timestamp:u})\n{n.Content}"));
    }
}

public sealed record NoteEntry(int Id, string Title, string Content, DateTime Timestamp);

// ── Tools exposed to the agent ──

public sealed class ResearchTools(Notepad notepad)
{
    [Description("Search the web for information on a query. Returns a list of results with titles, URLs, and snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query")] string query,
        [Description("Max number of results (1-5)")] int maxResults = 3)
    {
        maxResults = Math.Clamp(maxResults, 1, 5);

        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

        // Use DuckDuckGo instant-answer API (no key required)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await http.GetFromJsonAsync<DdgResponse>(url);
            var results = new List<string>();

            if (!string.IsNullOrWhiteSpace(json?.AbstractText))
                results.Add($"**Summary**: {json.AbstractText}\nSource: {json.AbstractURL}");

            if (json?.RelatedTopics is { Count: > 0 })
            {
                foreach (var topic in json.RelatedTopics.Take(maxResults))
                {
                    if (!string.IsNullOrWhiteSpace(topic.Text))
                        results.Add($"- {topic.Text}\n  URL: {topic.FirstURL}");
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No results found for '{query}'. Try rephrasing the query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a title and content. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Content of the note")] string content)
    {
        var id = notepad.Add(title, content);
        return $"Note #{id} saved: '{title}'";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        return notepad.FormatAll();
    }
}

// ── DuckDuckGo response models ──

public sealed class DdgResponse
{
    public string? AbstractText { get; set; }
    public string? AbstractURL { get; set; }
    public List<DdgTopic>? RelatedTopics { get; set; }
}

public sealed class DdgTopic
{
    public string? Text { get; set; }
    public string? FirstURL { get; set; }
}

// ── Hosted service that runs the agent ──

public sealed class ResearchAgentService(
    IChatClient chatClient,
    ResearchTools researchTools,
    Notepad notepad,
    IHostApplicationLifetime lifetime,
    ILoggerFactory loggerFactory) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine();
        Console.WriteLine("╔══════════════════════════════════════════╗");
        Console.WriteLine("║        🔍 Research Agent v1.0           ║");
        Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
        Console.WriteLine("╚══════════════════════════════════════════╝");
        Console.WriteLine();

        var tools = new List<AITool>
        {
            AIFunctionFactory.Create(ResearchTools.SearchWeb),
            AIFunctionFactory.Create(researchTools.SaveNote),
            AIFunctionFactory.Create(researchTools.GetNotes),
        };

        var agent = new ChatClientAgent(
            chatClient,
            instructions: """
                You are a research agent. When given a topic:
                1. Search the web for relevant information using multiple queries.
                2. Save important findings as notes using the note-taking tool.
                3. After gathering enough information, retrieve all notes and produce a
                   well-structured summary with key findings, organized by theme.
                Be thorough — use at least 2-3 different search queries per topic to get
                broad coverage. Always cite sources when available.
                """,
            name: "ResearchAgent",
            description: "An agent that researches topics by searching the web and taking notes.",
            tools: tools,
            loggerFactory: loggerFactory);

        while (!stoppingToken.IsCancellationRequested)
        {
            Console.Write("\n📝 Research topic: ");
            var topic = Console.ReadLine();

            if (string.IsNullOrWhiteSpace(topic))
                continue;

            if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
                break;

            Console.WriteLine($"\n🔬 Researching: {topic}\n");

            try
            {
                var session = await agent.CreateSessionAsync(
                    conversationId: Guid.NewGuid().ToString(),
                    cancellationToken: stoppingToken);

                await foreach (var update in agent.RunStreamingAsync(
                    $"Research the following topic thoroughly: {topic}",
                    session,
                    cancellationToken: stoppingToken))
                {
                    if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
                        Console.Write(update.Text);
                }

                Console.WriteLine("\n");

                // Show collected notes
                var notes = notepad.GetAll();
                if (notes.Count > 0)
                {
                    Console.WriteLine($"📋 {notes.Count} note(s) collected during research.");
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"\n❌ Error: {ex.Message}");
            }
        }

        Console.WriteLine("\nGoodbye! 👋");
        lifetime.StopApplication();
    }
}

