 // ── Notepad: in-memory store for research notes ──

 public sealed class Notepad
 {
     private readonly List<NoteEntry> _notes = [];
     private int _nextId = 1;

     public int Add(string title, string content)
     {
         var id = _nextId++;
         _notes.Add(new NoteEntry(id, title, content, DateTime.UtcNow));
         return id;
     }

     public IReadOnlyList<NoteEntry> GetAll() => _notes.AsReadOnly();

     public string FormatAll()
     {
         if (_notes.Count == 0)
             return "(no notes yet)";

         return string.Join("\n\n", _notes.Select(n =>
             $"[Note #{n.Id}] {n.Title} ({n.Timestamp:u})\n{n.Content}"));
     }
 }

 public sealed record NoteEntry(int Id, string Title, string Content, DateTime Timestamp);

 // ── Tools exposed to the agent ──

 public sealed class ResearchTools(Notepad notepad)
 {
     [Description("Search the web for information on a query. Returns a list of results with titles, URLs, and snippets.")]
     public static async Task<string> SearchWeb(
         [Description("The search query")] string query,
         [Description("Max number of results (1-5)")] int maxResults = 3)
     {
         maxResults = Math.Clamp(maxResults, 1, 5);

         using var http = new HttpClient();
         http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

         // Use DuckDuckGo instant-answer API (no key required)
         var encoded = Uri.EscapeDataString(query);
         var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

         try
         {
             var json = await http.GetFromJsonAsync<DdgResponse>(url);
             var results = new List<string>();

             if (!string.IsNullOrWhiteSpace(json?.AbstractText))
                 results.Add($"**Summary**: {json.AbstractText}\nSource: {json.AbstractURL}");

             if (json?.RelatedTopics is { Count: > 0 })
             {
                 foreach (var topic in json.RelatedTopics.Take(maxResults))
                 {
                     if (!string.IsNullOrWhiteSpace(topic.Text))
                         results.Add($"- {topic.Text}\n  URL: {topic.FirstURL}");
                 }
             }

             return results.Count > 0
                 ? string.Join("\n\n", results)
                 : $"No results found for '{query}'. Try rephrasing the query.";
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}. Try a different query.";
         }
     }

     [Description("Save a research note with a title and content. Use this to record important findings.")]
     public string SaveNote(
         [Description("Short title for the note")] string title,
         [Description("Content of the note")] string content)
     {
         var id = notepad.Add(title, content);
         return $"Note #{id} saved: '{title}'";
     }

     [Description("Retrieve all saved research notes.")]
     public string GetNotes()
     {
         return notepad.FormatAll();
     }
 }

