             Console.Write("\n📝 Research topic: ");
             var topic = Console.ReadLine();

             if (string.IsNullOrWhiteSpace(topic))
                 continue;

             if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
                 break;

             Console.WriteLine($"\n🔬 Researching: {topic}\n");

             try
             {
                 var session = await agent.CreateSessionAsync(
                     conversationId: Guid.NewGuid().ToString(),
                     cancellationToken: stoppingToken);

                 await foreach (var update in agent.RunStreamingAsync(
                     $"Research the following topic thoroughly: {topic}",
                     session,
                     cancellationToken: stoppingToken))
                 {
                     if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
                         Console.Write(update.Text);
                 }

                 Console.WriteLine("\n");

                 // Show collected notes
                 var notes = notepad.GetAll();
                 if (notes.Count > 0)
                 {
                     Console.WriteLine($"📋 {notes.Count} note(s) collected during research.");
                 }
             }
             catch (OperationCanceledException)
             {
                 break;
             }
             catch (Exception ex)
             {
                 Console.WriteLine($"\n❌ Error: {ex.Message}");
             }
         }

         Console.WriteLine("\nGoodbye! 👋");
         lifetime.StopApplication();
     }
 }
